window.Q_DATA=(window.Q_DATA||[]).concat([{"id":"R0702B-17","examCode":"R0702B","exam":"令和7年2月 B","number":17,"field":"アンテナ・電波伝搬","topic":"パラボラアンテナ","answer":5,"image":"data:image/jpeg;base64,","text":"〔17〕 18〔GHz〕の周波数の電波で使用する、回転放物面の開口面積が0.4〔m2〕で絶対利得が40〔dB〕のパラボラアンテナの開口 効率の値として、最も近いものを下の番号から選べ。 1 35〔%〕 2 40〔%〕 3 45〔%〕 4 50〔%〕 5 55〔%〕","explanation":"<div class=\"ex-id\">R0702B-17｜パラボラアンテナ</div><h4>式</h4><p>η=Gλ²/(4πA)。40dBはG=10000です。</p><h4>波長</h4><p>18GHzでは λ=3×10⁸/(18×10⁹)=<strong>1/60m≈0.0167m</strong>。</p><h4>開口効率</h4><p>η≈10000×(1/60)² /(4π×0.4)≈0.55。</p><p>したがって最も近いのは<strong>55%</strong>、選択肢5です。</p><h4>注意</h4><p>40dBを式へそのまま代入せず、利得を真数10000へ戻してから計算します。</p><h4>理解の補足</h4><p>開口効率ηは、同じ物理開口面積が理想的に使えた場合の利得に対して、実際にどれだけ有効利用できているかを表します。照射のむら、スピルオーバ、位相誤差などで100%にはなりません。</p><h4>試験での確認</h4><p>G=η4πA/λ²より、面積Aが大きい・波長λが短い・効率ηが高いほど利得が上がります。dB利得は必ず真数へ戻してからηを求めます。</p>","choices":5,"stemText":"18〔GHz〕の周波数の電波で使用する、回転放物面の開口面積が0.4〔m2〕で絶対利得が40〔dB〕のパラボラアンテナの開口効率の値として、最も近いものを下の番号から選べ。","choiceTexts":["35〔%〕","40〔%〕","45〔%〕","50〔%〕","55〔%〕"],"showFigure":false,"textExtractConfidence":"high","visualChoices":false,"solveMode":"calculation","calcLevel":"written","choiceReasons":["40dBは真数10000、18GHzではλ≈1/60mです。η=Gλ^2/(4πA)を計算すると約55%なので、35%では効率が低すぎ、同じ条件で40dBの利得に届きません。","必要な開口効率は約55%です。40%では15ポイント不足し、同じ面積・周波数なら得られる利得が40dBより小さくなります。","45%は正しい約55%より10ポイント低く、G=η4πA/λ^2へ戻すと要求利得10000を満たしません。","50%はかなり近いものの、式から得られる約55%よりまだ低い値です。『最も近いもの』としても55%の選択肢があるため不正解です。","G=10000、λ≈1/60m、A=0.4m^2を代入するとη≈0.55です。55%が最も近く、この選択肢が正解です。"]},{"id":"R0702B-21","examCode":"R0702B","exam":"令和7年2月 B","number":21,"field":"アンテナ・電波伝搬","topic":"半波長ダイポール","answer":3,"image":"data:image/jpeg;base64,","text":"〔21〕 自由空間において、半波長ダイポールアンテナに対する相対利得が13〔dB〕の指向性アンテナに5〔W〕の電力を供給して電 波を放射したとき、最大放射方向で送信点からの距離が10〔km〕の受信点における電界強度の値として、最も近いものを下の 番号から選べ。ただし、電界強度 E は、放射電力を P〔W〕、送受信点間の距離を d〔m〕、半波長ダイポールアンテナに対する アンテナの相対利得をG (真数)とすると、次式で表されるものとする。また、アンテナ及び給電系の損失はないものとし、 log₁₀2＝0.3 とする。 E = 7√GP d 〔V/m〕 1 3〔mV/m〕 2 5〔mV/m〕 3 7〔mV/m〕 4 9〔mV/m〕 5 11〔mV/m〕","explanation":"<div class=\"ex-id\">R0702B-21｜半波長ダイポール</div><h4>利得を真数へ</h4><p>13dBの相対利得はG≈20。P=5Wなので GP=100、√GP=10。</p><h4>電界強度</h4><p>E=7√(GP)/d=7×10/10000=<strong>0.007V/m=7mV/m</strong>。</p><p>よって選択肢3です。</p><h4>確認</h4><p>距離が10kmなので分母は10000m。mV/mへ直す最後の単位変換を忘れないこと。</p><h4>理解の補足</h4><p>半波長ダイポールは基準アンテナとして頻出します。相対利得dBdは半波長ダイポール基準、絶対利得dBiは等方性アンテナ基準で、両者には約2.15dBの差があります。</p><h4>試験での確認</h4><p>この式ではE∝√(GP)/dです。したがって、送信電力や利得を4倍にすると電界強度は2倍、距離を2倍にすると電界強度は1/2になります。dBで与えられた利得は、そのままGへ代入せず必ず真数へ戻してから平方根を取ります。</p>","choices":5,"stemText":"自由空間において、半波長ダイポールアンテナに対する相対利得が13〔dB〕の指向性アンテナに5〔W〕の電力を供給して電波を放射したとき、最大放射方向で送信点からの距離が10〔km〕の受信点における電界強度の値として、最も近いものを下の番号から選べ。ただし、電界強度 E は、放射電力をP〔W〕、送受信点間の距離をd〔m〕、半波長ダイポールアンテナに対するアンテナの相対利得をG(真数)とすると、次式で表されるものとする。また、アンテナ及び給電系の損失はないものとし、log₁₀2＝0.3とする。E＝7√(GP)/d〔V/m〕","choiceTexts":["3〔mV/m〕","5〔mV/m〕","7〔mV/m〕","9〔mV/m〕","11〔mV/m〕"],"showFigure":false,"textExtractConfidence":"high","visualChoices":false,"solveMode":"calculation","calcLevel":"written","choiceReasons":["G=20、P=5Wなので7√(GP)=70です。距離10kmではE=70/10000=7mV/mとなるため、3mV/mでは小さすぎます。","同じ計算で電界強度は7mV/mです。5mV/mは正しい値より2mV/m低く、利得13dBを真数20へ戻した条件と一致しません。","13dB→G=20、GP=100、√GP=10です。E=7×10/10000=0.007V/m=7mV/mとなるため、この選択肢が正解です。","9mV/mは正しい7mV/mより大きく、同じ送信電力・利得なら受信点が10kmより近い場合に相当する値です。","11mV/mは正しい値を大きく上回ります。10kmという距離とG=20、P=5Wを式へ入れた結果にはなりません。"]},{"id":"R0706A-03","examCode":"R0706A","exam":"令和7年6月 A","number":3,"field":"電気・電子回路","topic":"回路1","answer":4,"image":"data:image/jpeg;base64,","text":"〔３〕 図に示す抵抗R1、R2、R3 及びR4 の回路において、R4 を流れる電流I4 が1.5〔A〕であるとき、直流電源電圧V の値として、 正しいものを下の番号から選べ。 1 13.5〔V〕 2 30.0〔V〕 3 43.5〔V〕 4 54.0〔V〕 5 67.5〔V〕","explanation":"<div class=\"ex-id\">R0706A-03｜直並列抵抗の逆算</div><h4>① R₄から電圧を出す</h4><p>R₄=9ΩにI₄=1.5Aが流れているので、R₄の両端電圧は <strong>V₄=9×1.5=13.5V</strong> です。</p><h4>② 同じ並列部分をまとめる</h4><p>図の45Ω・15Ω・9Ωは並列なので、<strong>1/R₀=1/45+1/15+1/9=(1+3+5)/45=1/5</strong>。したがって <strong>R₀=5Ω</strong> です。この並列部分全体にも13.5Vが加わっているため、流れ込む合成電流は <strong>I₀=13.5/5=2.7A</strong> です。</p><h4>③ 左側の15Ωの電圧降下を求める</h4><p>並列部分へ入る2.7Aは、その手前の15Ωにも流れます。したがって電圧降下は <strong>V₁=15×2.7=40.5V</strong> です。</p><h4>④ 電源電圧を足す</h4><p>電源電圧は、左側15Ωの40.5Vと並列部分の13.5Vの和なので、<strong>V=40.5+13.5=54.0V</strong>。選択肢4です。</p><h4>見方</h4><p>この問題は合成抵抗を全部作るより、既知のI₄から<strong>電流→電圧→並列全体の電流→手前の電圧</strong>と逆向きにたどる方が簡単です。</p>","choices":5,"stemText":"図に示す抵抗R1、R2、R3及びR4の回路において、R4を流れる電流I4が1.5〔A〕であるとき、直流電源電圧Vの値として、正しいものを下の番号から選べ。","choiceTexts":["13.5〔V〕","30.0〔V〕","43.5〔V〕","54.0〔V〕","67.5〔V〕"],"showFigure":true,"textExtractConfidence":"high","visualChoices":false,"solveMode":"calculation","calcLevel":"written","choiceReasons":["R4=9Ωに1.5Aなので並列部分には13.5Vが必要です。13.5Vは並列部分だけの電圧で、さらに手前の15Ωで40.5V落ちるため、13.5Vを電源電圧とすることはできません。","並列部分は5Ωなので合成電流は13.5/5=2.7Aです。手前の15Ωだけで40.5V必要になるため、電源30.0Vではその電圧降下すら賄えません。","手前の15Ωの電圧降下が40.5Vです。これに並列部分の13.5Vを足す必要があるため、43.5Vでは10.5V不足します。","R4から13.5V、並列合成5Ωから2.7A、手前15Ωから40.5Vと求まり、電源は40.5+13.5=54.0Vです。この選択肢が正解です。","回路に必要な電源電圧は54.0Vです。67.5Vでは13.5V大きく、R4=9Ωに1.5Aという出発条件から逆算した各電圧降下と一致しません。"]},{"id":"R0706A-04","examCode":"R0706A","exam":"令和7年6月 A","number":4,"field":"電気・電子回路","topic":"回路2","answer":5,"image":"data:image/jpeg;base64,","text":"〔４〕 図に示す回路において、スイッチS1のみを閉じたときの電流I とスイッチS2 のみを閉じたときの電流I は、ともに5〔A〕で あった。また、スイッチS1 とS2 の両方を閉じたときの電流I は、3〔A〕であった。抵抗R 及びコンデンサC のリアクタンス XC の大きさの値の組合せとして、正しいものを下の番号から選べ。ただし、交流電源電圧は240〔V〕とする。 R XC 1 40〔Ω〕 15〔Ω〕 2 40〔Ω〕 30〔Ω〕 3 40〔Ω〕 60〔Ω〕 4 80〔Ω〕 30〔Ω〕 5 80〔Ω〕 60〔Ω〕","explanation":"<div class=\"ex-id\">R0706A-04｜RLC並列回路・スイッチ</div><h4>① 片方ずつ閉じた条件を見る</h4><p>S₁だけでもS₂だけでも電源240Vに対する電流が5Aで同じです。Rは共通なので、RとLの並列回路、RとCの並列回路のインピーダンスの大きさが等しくなります。したがって <strong>X_L=X_C</strong> と分かります。</p><h4>② 両方閉じた条件からRを求める</h4><p>LとCを両方接続すると、X_L=X_Cなので誘導性サセプタンスと容量性サセプタンスが互いに打ち消し合います。入力から見るとリアクタンス成分が消え、合成インピーダンスは<strong>Rだけ</strong>になります。</p><p>両方閉じたときは240Vで3Aなので、<strong>R=Z=240/3=80Ω</strong> です。</p><h4>③ 片側だけの条件からX_Cを求める</h4><p>S₂だけを閉じたとき、合成インピーダンスの大きさは <strong>|Z|=240/5=48Ω</strong>。RとCの並列では、<strong>|Z|=RX_C/√(R²+X_C²)</strong> です。</p><p>R=80Ωを代入すると、48=80X_C/√(6400+X_C²)。両辺を二乗して整理すると、<strong>X_C²=3600</strong>。よって <strong>X_C=60Ω</strong> です。</p><h4>結論</h4><p><strong>R=80Ω、X_C=60Ω</strong> なので選択肢5です。</p><h4>混同防止</h4><p>両方閉じたときの電流を「5A+5A」と足してはいけません。LとCの電流は位相が逆向きなので、この問題ではむしろリアクティブ成分が相殺されます。</p>","choices":5,"stemText":"図に示す回路において、スイッチS1のみを閉じたときの電流IとスイッチS2のみを閉じたときの電流Iは、ともに5〔A〕であった。また、スイッチS1とS2の両方を閉じたときの電流Iは、3〔A〕であった。抵抗R及びコンデンサ C のリアクタンスXCの大きさの値の組合せとして、正しいものを下の番号から選べ。ただし、交流電源電圧は240〔V〕とする。","choiceTexts":["R：40〔Ω〕｜X_C：15〔Ω〕","R：40〔Ω〕｜X_C：30〔Ω〕","R：40〔Ω〕｜X_C：60〔Ω〕","R：80〔Ω〕｜X_C：30〔Ω〕","R：80〔Ω〕｜X_C：60〔Ω〕"],"showFigure":true,"textExtractConfidence":"high","visualChoices":false,"solveMode":"calculation","calcLevel":"written","choiceReasons":["両方閉じたときLとCのサセプタンスが相殺され、合成インピーダンスはRです。240V/3A=80Ωなので、R=40Ωの時点で条件に合いません。XCも正しくは60Ωです。","両方閉じた条件からR=80Ωに決まるため、R=40Ωが誤りです。また片側だけで|Z|=48Ωを満たすXCは60Ωで、30Ωでもありません。","XC=60Ωは正しいですが、Rが誤りです。両スイッチONでリアクタンス分が相殺されるため、R=240/3=80Ωでなければなりません。","R=80Ωは正しいですが、XC=30Ωではありません。48=80XC/√(6400+XC²)を解くとXC=60Ωです。","両方ONからR=80Ω、片側ONの|Z|=48ΩからXC=60Ωと求まります。三つの測定条件をすべて満たすため、この選択肢が正解です。"]},{"id":"R0706A-05","examCode":"R0706A","exam":"令和7年6月 A","number":5,"field":"電気・電子回路","topic":"共振回路","answer":2,"image":"data:image/jpeg;base64,","text":"〔５〕 次の記述は、図1 及び図2 に示す共振回路について述べたものである。このうち誤っているものを下の番号から選べ。ただ し、ω0〔rad/s〕は共振角周波数とする。 1 図1 の共振時の回路の合成インピーダンスは、R1 である。 2 図1 の共振回路のQ (尖鋭度)は、Q = ω0CR1 である。 3 図2 の共振回路のQ (尖鋭度)は、Q = R2 ω0L である。 4 図2 の共振角周波数 ω0 は、ω0 = □ √LC である。","explanation":"<div class=\"ex-id\">R0706A-05｜共振回路</div><h4>基本式</h4><p>直列RLCのQは Q=ω₀L/R₁=1/(ω₀CR₁)。並列RLCのQは Q=R₂/(ω₀L)=ω₀CR₂。共振角周波数はω₀=1/√(LC)です。</p><h4>各選択肢</h4><ul><li>1：直列共振時の合成インピーダンスはR₁。正しい。</li><li>2：「Q=ω₀CR₁」は<strong>誤り</strong>。正しくは1/(ω₀CR₁)。</li><li>3：並列Q=R₂/(ω₀L)。正しい。</li><li>4：ω₀=1/√(LC)。正しい。</li></ul><p>したがって正答は<strong>2</strong>です。</p><h4>理解の補足</h4><p>共振は、コイルとコンデンサのリアクタンスが大きさとして等しくなり、互いの効果が打ち消し合う状態です。直列共振では入力から見たリアクタンスが消えるのでZが最小・Iが最大。並列共振では入力電流が小さくなり、入力インピーダンスが大きくなる方向です。</p><h4>試験での確認</h4><p>Qの式は、直列なら「リアクタンス÷抵抗」、並列なら「抵抗÷リアクタンス」と整理すると強いです。ω₀L=1/(ω₀C)も同時に覚えると、Qの等価な二つの式を相互変換できます。</p>","choices":4,"stemText":"次の記述は、図1及び図2に示す共振回路について述べたものである。このうち誤っているものを下の番号から選べ。ただし、ω₀〔rad/s〕は共振角周波数とする。","choiceTexts":["図1の共振時の回路の合成インピーダンスは、R₁である。","図1の共振回路のQ（尖鋭度）は、Q＝ω₀CR₁である。","図2の共振回路のQ（尖鋭度）は、Q＝R₂/(ω₀L)である。","図2の共振角周波数ω₀は、ω₀＝1/√(LC)である。"],"showFigure":true,"textExtractConfidence":"high","visualChoices":true,"choiceReasons":["直列共振ではLと C のリアクタンスが相殺されるため、図1の合成インピーダンスはR₁になります。","図1（直列RLC）のQはω₀L/R₁です。ω₀CR₁はその逆数側の形なので誤りです。","並列共振では共振条件 ω₀L＝1/(ω₀C) が成り立ち、Qは無効電流と抵抗電流の比から Q＝R₂/(ω₀L)＝ω₀CR₂ と表せます。したがって R₂/(ω₀L) は正しい式です。","共振条件ω₀L＝1/(ω₀ C )から、図2の共振角周波数はω₀＝1/√(LC)になります。"],"solveMode":"text","calcLevel":"none"},{"id":"R0706A-07","examCode":"R0706A","exam":"令和7年6月 A","number":7,"field":"電気・電子回路","topic":"オペアンプ","answer":4,"image":"data:image/jpeg;base64,","text":"〔７〕 図に示す理想的な演算増幅器(AOP)を使用した反転増幅回路の電圧利得の値として、最も近いものを下の番号から選べ。ただ し、log₁₀2＝0.3 とする。 1 6〔dB〕 2 8〔dB〕 3 10〔dB〕 4 12〔dB〕 5 16〔dB〕","explanation":"<div class=\"ex-id\">R0706A-07｜オペアンプ</div><h4>考え方</h4><p>反転増幅回路では |Aᵥ|=R₂/R₁。図の抵抗比を読むと利得の大きさは<strong>4倍</strong>です。</p><h4>dB化</h4><p>20log₁₀4=20log₁₀(2²)=40×0.3=<strong>12dB</strong>。</p><p>したがって選択肢4です。</p><h4>注意</h4><p>反転なので電圧利得そのものにはマイナス符号が付きますが、dB値では利得の大きさ|Aᵥ|を使います。</p><h4>理解の補足</h4><p>理想オペアンプの負帰還回路では、入力電流は0、反転入力と非反転入力の電位はほぼ等しいとみなせます。反転入力が仮想接地になるため、入力抵抗を流れた電流がそのまま帰還抵抗へ流れ、抵抗比だけで利得が決まります。</p><h4>試験での確認</h4><p>「反転」なら符号はマイナス、「利得の大きさ」なら絶対値。dB化するときは電圧比なので20logです。ここを3段階に分けると混乱しません。</p>","choices":5,"stemText":"図に示す理想的な演算増幅器(AOP)を使用した反転増幅回路の電圧利得の値として、最も近いものを下の番号から選べ。ただし、log₁₀2＝0.3とする。","choiceTexts":["6〔dB〕","8〔dB〕","10〔dB〕","12〔dB〕","16〔dB〕"],"showFigure":true,"textExtractConfidence":"high","visualChoices":false,"solveMode":"calculation","calcLevel":"written","choiceReasons":["図の抵抗比から|Av|=4です。6dBは電圧比約2倍に相当し、4倍の利得を表せません。","8dBは電圧比約2.5倍です。抵抗比4倍より小さく、反転増幅器の利得の大きさと一致しません。","10dBは電圧比約3.16倍に相当します。実際の|Av|=4より小さいため誤りです。","|Av|=R2/R1=4で、20log10 4=20×2×0.3=12dBです。この選択肢が正解です。","16dBを電圧比へ戻すと10^(16/20)＝10^0.8≒6.3倍です。図の反転増幅回路は抵抗比から|Aᵥ|＝4倍なので、16dBでは利得を大きく見積もりすぎています。"]},{"id":"R0706B-03","examCode":"R0706B","exam":"令和7年6月 B","number":3,"field":"電気・電子回路","topic":"回路1","answer":1,"image":"data:image/jpeg;base64,","text":"〔３〕 図に示す抵抗R1、R2、R3 及びR4 の回路において、R1 の両端の電圧が75〔V〕であるとき、R4 を流れる電流I4 の値として、 正しいものを下の番号から選べ。 1 4.5〔A〕 2 6.0〔A〕 3 10.5〔A〕 4 15.0〔A〕 5 20.0〔A〕 75〔V〕 R3 = 20〔Ω〕 I4 R1 = 12.5〔Ω〕 R2 = 60〔Ω〕 直流電源電圧 R4 = 5〔Ω〕","explanation":"<div class=\"ex-id\">R0706B-03｜回路1</div><h4>進め方</h4><p>R₁の両端75Vが与えられているので、まずI₁=75/R₁でR₁枝の電流を求めます。図の接続関係に従い、同じ電圧を持つ枝はV=IRで、分岐点では電流保存で値を伝えていきます。</p><p>R₁=12.5ΩなのでI₁=6A。そこからR₂=60Ω、R₃=20Ω、R₄=5Ωの枝へ順に電圧・電流を追うと、R₄の電流は<strong>4.5A</strong>。選択肢1です。</p><h4>コツ</h4><p>既知の「75V」を出発点にして、図へ電流と電圧を書き込むと見失いにくいです。</p><h4>理解の補足</h4><p>回路図では、式を覚えるより先に「同じ二点につながっているか」「一本道か」「分岐点か」を確認します。並列なら電圧が共通、直列なら電流が共通、分岐点では電流保存です。交流でLやCが入る場合だけ、位相を持つ量としてインピーダンスを扱います。</p><h4>試験での確認</h4><p>計算後は、求めた値を元の図へ戻してV=IRや電流保存が成立するかを一度確認すると、枝の取り違えをかなり防げます。単位もV・A・Ω・Wのどれを答えているか最後に確認します。</p>","choices":5,"stemText":"図に示す抵抗R1、R2、R3及びR4の回路において、R1の両端の電圧が75〔V〕であるとき、R4を流れる電流I4の値として、正しいものを下の番号から選べ。","choiceTexts":["4.5〔A〕","6.0〔A〕","10.5〔A〕","15.0〔A〕","20.0〔A〕"],"showFigure":true,"textExtractConfidence":"high","visualChoices":false,"solveMode":"calculation","calcLevel":"written","choiceReasons":["R1の75VからI1=6Aを求め、図の接続に従って各枝の電圧・電流を順に伝えるとI4=4.5Aになります。この選択肢が正解です。","6.0Aは出発点で求めるR1の電流I1そのものです。求めるのはR4の電流であり、分岐後のI4とI1を同一視してはいけません。","10.5AではR4枝へ流れる電流を大きく見積もりすぎています。分岐点の電流保存を図に適用するとI4は4.5Aに決まります。","15.0Aは正しいI4の3倍以上です。R1=12.5Ω、R2=60Ω、R3=20Ω、R4=5Ωの接続関係をV=IRで追うとこの値にはなりません。","20.0AはR4=5Ωに対して非常に大きな電圧降下を要求し、75Vから始めて求めた各節点電圧と両立しません。"]},{"id":"R0706B-04","examCode":"R0706B","exam":"令和7年6月 B","number":4,"field":"電気・電子回路","topic":"回路2","answer":4,"image":"data:image/jpeg;base64,","text":"〔４〕 図に示す回路において、スイッチS1のみを閉じたときの電流I とスイッチS2 のみを閉じたときの電流I は、ともに5〔A〕で あった。また、スイッチS1 とS2 の両方を閉じたときの電流I は、4〔A〕であった。抵抗R 及びコイルL のリアクタンスXL の 大きさの値の組合せとして、正しいものを下の番号から選べ。ただし、交流電源電圧は150〔V〕とする。 R XL 1 18.2〔Ω〕 30〔Ω〕 2 18.2〔Ω〕 50〔Ω〕 3 18.2〔Ω〕 75〔Ω〕 4 37.5〔Ω〕 50〔Ω〕 5 37.5〔Ω〕 75〔Ω〕 S1 S2 I R 交流電源電圧 C L C：コンデンサ C L R1 図1 交 流 電 源 R1、R2：抵抗〔Ω〕 L：インダクタンス〔H〕 C：静電容量〔F〕 C 図2 R2 L 交 流 電 源","explanation":"<div class=\"ex-id\">R0706B-04｜交流回路・スイッチ</div><h4>回路の見方</h4><p>R、L、Cは交流電源に対して並列です。S₁を閉じるとL枝、S₂を閉じるとC枝が接続されます。抵抗電流I<sub>R</sub>は電圧と同相、コイル電流I<sub>L</sub>は90°遅れ、コンデンサ電流I<sub>C</sub>は90°進みます。</p><h4>① S₁だけ・S₂だけの条件</h4><p>S₁だけのときはRとLの並列なので、全電流の大きさは <strong>√(I<sub>R</sub>²+I<sub>L</sub>²)=5A</strong>。</p><p>S₂だけのときはRとCの並列なので、<strong>√(I<sub>R</sub>²+I<sub>C</sub>²)=5A</strong>。</p><p>左辺のI<sub>R</sub>は共通で、どちらも5Aなので <strong>I<sub>L</sub>=I<sub>C</sub></strong> と分かります。したがってX<sub>L</sub>とX<sub>C</sub>の大きさも等しくなります。</p><h4>② 両方閉じた条件からRを求める</h4><p>Lの電流とCの電流は互いに180°反対向きの無効電流成分です。I<sub>L</sub>=I<sub>C</sub>なので、両方を閉じるとこの二つは相殺されます。</p><p>したがって電源から見える全電流4Aは抵抗電流I<sub>R</sub>そのものです。よって <strong>R=V/I<sub>R</sub>=150/4=37.5Ω</strong>。</p><h4>③ 単独時5AからX<sub>L</sub>を求める</h4><p>S₁だけのとき、5²=4²+I<sub>L</sub>²。したがって I<sub>L</sub>=√(25−16)=<strong>3A</strong>。</p><p>コイル枝にも150Vが加わるので、<strong>X<sub>L</sub>=150/3=50Ω</strong>。</p><h4>結論</h4><p>R=<strong>37.5Ω</strong>、X<sub>L</sub>=<strong>50Ω</strong>。したがって選択肢4です。</p><h4>注意</h4><p>5A+5Aや5A−5Aのように電流の大きさだけを足し引きしてはいけません。抵抗・L・Cでは位相が異なるので、直交する成分として扱います。</p><h4>試験での確認</h4><p>この型は「RLだけとRCだけが同じ電流→LとCの無効電流が等しい→両方接続で相殺」という流れを見ると、計算量がかなり減ります。</p>","choices":5,"stemText":"図に示す回路において、スイッチS1のみを閉じたときの電流IとスイッチS2のみを閉じたときの電流Iは、ともに5〔A〕であった。また、スイッチS1とS2の両方を閉じたときの電流Iは、4〔A〕であった。抵抗R及びコイルLのリアクタンスXLの大きさの値の組合せとして、正しいものを下の番号から選べ。ただし、交流電源電圧は150〔V〕とする。","choiceTexts":["R：18.2〔Ω〕｜X_L：30〔Ω〕","R：18.2〔Ω〕｜X_L：50〔Ω〕","R：18.2〔Ω〕｜X_L：75〔Ω〕","R：37.5〔Ω〕｜X_L：50〔Ω〕","R：37.5〔Ω〕｜X_L：75〔Ω〕"],"showFigure":true,"textExtractConfidence":"high","visualChoices":false,"solveMode":"calculation","calcLevel":"written","choiceReasons":["正しい組はR=37.5Ω、XL=50Ωです。この選択肢はR=18.2Ωが誤りで、XL=30Ωも誤っています。","XL=50Ωは正しい値ですが、R=18.2Ωが誤りです。単独時5Aと両方時4Aをフェーザで同時に満たすとR=37.5Ωになります。","R=18.2ΩもXL=75Ωも条件と一致しません。交流枝電流の位相差を含めるとこの組合せでは三つの測定値を再現できません。","R=37.5Ω、XL=50Ωが三つのスイッチ条件を同時に満たすため、この選択肢が正解です。","R=37.5Ωは正しいですが、XL=75Ωが誤りです。コイル枝のリアクタンスは50Ωでないと、両方を閉じたときの4Aを満たしません。"]}]);
